arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_acf1886d3efa4efa8f2de91150fe040c.Models
@using sv_acf1886d3efa4efa8f2de91150fe040c.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success mt-4">
        <h4>Application Submitted Successfully!</h4>
        <p>Your application ID is: <strong>@_applicationId</strong></p>
        <p>Thank you for applying. We will review your application and get back to you.</p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="step-indicator mb-4">
        <ol class="step-list">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var stepClass = GetStepClass(stepIndex);
                <li class="step-item @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                    <span class="step-badge">
                        @if (_completedSteps.Contains(stepIndex))
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            @(stepIndex + 1)
                        }
                    </span>
                    <span class="step-label">@_stepNames[stepIndex]</span>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <div class="step-content">
            <h3>Personal Information</h3>
            <div class="mb-3">
                <label class="form-label">Full Name *</label>
                <input type="text" class="form-control" @bind="_fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email *</label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone *</label>
                <input type="tel" class="form-control" @bind="_phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address *</label>
                <input type="text" class="form-control" @bind="_address" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span>Validating...</span>
                    }
                    else
                    {
                        <span>Next</span>
                    }
                </button>
            </div>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (_currentStep == 1)
    {
        <div class="step-content">
            <h3>Work History</h3>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Position @(index + 1)</h5>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Company Name *</label>
                            <input type="text" class="form-control" @bind="_workEntries[index].Company" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Job Title *</label>
                            <input type="text" class="form-control" @bind="_workEntries[index].Title" />
                        </div>
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Start Date *</label>
                                <input type="date" class="form-control" @bind="_workEntries[index].StartDate" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
                                <div class="form-check mt-1">
                                    <input type="checkbox" class="form-check-input" id="current-@index" @bind="_workEntries[index].IsCurrent" />
                                    <label class="form-check-label" for="current-@index">I currently work here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="3" @bind="_workEntries[index].Description"></textarea>
                        </div>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </div>
    }

    <!-- Step 3: References -->
    @if (_currentStep == 2)
    {
        <div class="step-content">
            <h3>References</h3>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h5 class="card-title mb-0">Reference @(index + 1)</h5>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Name *</label>
                            <input type="text" class="form-control" @bind="_references[index].Name" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Relationship *</label>
                            <input type="text" class="form-control" @bind="_references[index].Relationship" />
                        </div>
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Email *</label>
                                <input type="email" class="form-control" @bind="_references[index].Email" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Phone *</label>
                                <input type="tel" class="form-control" @bind="_references[index].Phone" />
                            </div>
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (_currentStep == 3)
    {
        <div class="step-content">
            <h3>Cover Letter</h3>
            <div class="mb-3">
                <textarea class="form-control" rows="12" @bind="_coverLetter" @bind:event="oninput" maxlength="2000"></textarea>
                <div class="form-text text-end">@_coverLetter.Length / 2000 characters</div>
            </div>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (_currentStep == 4)
    {
        <div class="step-content">
            <h3>Review & Submit</h3>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5 class="card-title">Personal Information</h5>
                        <button class="btn btn-sm btn-link" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5 class="card-title">Work History</h5>
                        <button class="btn btn-sm btn-link" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-2 border-bottom pb-2">
